n// light read it. Azimuth on x (world), elevation on y, with more texels near the horizon.\n\nuniform vec3 sunDir;\nuniform vec3 moonDir;\nuniform float moonSky;  // moonlight on the sky, relative to the sun\nuniform vec2 lutSize;\n\nout vec4 fragColor;\n\nconst float PI = 3.14159265;\nconst float R_GROUND = 6360.0; // km\nconst float R_TOP = 6460.0;\nconst float VIEWER_ALTITUDE = 0.2;\nconst vec3 RAYLEIGH = vec3(5.802, 13.558, 33.1) * 1e-3; // scattering, km^-1 (same constants as daylight.js)\nconst float H_RAYLEIGH = 8.0;\nconst float MIE_SCATTERING = 0.004;                      // haze of a clear sky\nconst float MIE_EXTINCTION = 0.0044;\nconst float H_MIE = 1.2;\nconst float MIE_G = 0.8;\nconst vec3 OZONE = vec3(0.65, 1.881, 0.085) * 1e-3;     // absorption, in a layer around 25 km\nconst float SKY_INTENSITY = 14.0;\nconst vec3 AIRGLOW = vec3(0.0004, 0.0007, 0.0016);       // night sky without moon\nconst int VIEW_STEPS = 32;\nconst int LIGHT_STEPS = 8;\n\nvec3 extinction(float h) {\n    return RAYLEIGH * exp(-h / H_RAYLEIGH) + MIE_EXTINCTION * exp(-h / H_MIE) + OZONE * max(0.0, 1.0 - abs(h - 25.0) / 15.0);\n}\n\n// distance to the far side of a sphere centered on the planet, from inside\nfloat exitSphere(vec3 ro, vec3 rd, float r) {\n    float b = dot(ro, rd), c = dot(ro, ro) - r * r;\n    return -b + sqrt(max(b * b - c, 0.0));\n}\n\n// distance to the ground, or -1\nfloat hitGround(vec3 ro, vec3 rd) {\n    float b = dot(ro, rd), c = dot(ro, ro) - R_GROUND * R_GROUND;\n    float d = b * b - c;\n    if(d < 0.0) return -1.0;\n    float t = -b - sqrt(d);\n    return t > 0.0 ? t : -1.0;\n}\n\nvec3 transmittanceToLight(vec3 p, vec3 l) {\n    if(hitGround(p, l) > 0.0) return vec3(0.0); // behind the planet\n    float dt = exitSphere(p, l, R_TOP) / float(LIGHT_STEPS);\n    vec3 depth = vec3(0.0);\n    for(int i = 0; i < LIGHT_STEPS; i++) {\n        depth += extinction(length(p + l * (float(i) + 0.5) * dt) - R_GROUND) * dt;\n    }\n    return exp(-depth);\n}\n\nfloat rayleighPhase(float mu) {\n    return 3.0 / (16.0 * PI) * (1.0 + mu * mu);\n}\n\nfloat miePhase(float mu) { // Cornette-Shanks\n    float g2 = MIE_G * MIE_G;\n    return 3.0 / (8.0 * PI) * (1.0 - g2) * (1.0 + mu * mu) / ((2.0 + g2) * pow(1.0 + g2 - 2.0 * MIE_G * mu, 1.5));\n}\n\nvoid main() {\n    vec2 uv = gl_FragCoord.xy / lutSize;\n    float azimuth = (uv.x - 0.5) * 2.0 * PI;\n    float s = uv.y * 2.0 - 1.0;\n    float elevation = sign(s) * s * s * 0.5 * PI;\n    vec3 dir = vec3(cos(elevation) * cos(azimuth), cos(elevation) * sin(azimuth), sin(elevation));\n\n    vec3 ro = vec3(0.0, 0.0, R_GROUND + VIEWER_ALTITUDE);\n    float ground = hitGround(ro, dir);\n    float tMax = ground > 0.0 ? ground : exitSphere(ro, dir, R_TOP);\n    float dt = tMax / float(VIEW_STEPS);\n\n    float muSun = dot(dir, sunDir), muMoon = dot(dir, moonDir);\n    vec3 transmittance = vec3(1.0), radiance = vec3(0.0);\n    for(int i = 0; i < VIEW_STEPS; i++) {\n        vec3 p = ro + dir * (float(i) + 0.5) * dt;\n        float h = length(p) - R_GROUND;\n        float rayleigh = exp(-h / H_RAYLEIGH), mie = exp(-h / H_MIE);\n        vec3 light = (RAYLEIGH * rayleigh * rayleighPhase(muSun) + MIE_SCATTERING * mie * miePhase(muSun)) * transmittanceToLight(p, sunDir);\n        if(moonSky > 0.0) {\n            light += moonSky * (RAYLEIGH * rayleigh * rayleighPhase(muMoon) + MIE_SCATTERING * mie * miePhase(muMoon)) * transmittanceToLight(p, moonDir);\n        }\n        radiance += transmittance * light * dt;\n        transmittance *= exp(-extinction(h) * dt);\n    }\n    fragColor = vec4(radiance * SKY_INTENSITY + AIRGLOW, 1.0);\n}\n"},136:e=>{e.exports="#version 300 es\n\nout vec2 vNdc;\n\nvoid main() {\n    // one triangle covering the screen, no vertex buffer\n    vec2 p = vec2(float((gl_VertexID & 1) << 2) - 1.0, float((gl_VertexID & 2) << 1) - 1.0);\n    vNdc = p;\n    // on the far plane: with depthFunc LEQUAL only the pixels without terrain are shaded\n    gl_Position = vec4(p, 1.0, 1.0);\n}\n"},67:e=>{e.exports="#version 300 es\nprecision highp float;\nprecision highp int;\n\n// Generates one layer of the voxel textures (run once at startup, textures.js): realistic, tileable (every noise is\n// periodic over the texture), with a relief turned into a normal map. Layers: 0 earth, 1 rock, 2 grass, 3 snow, 4 sand,\n// 5 water ripples (only its normal map is used, by water_fragment.glsl).\n\nuniform int layer;\nuniform float size; // texels per side\n\nlayout(location = 0) out vec4 outAlbedo; // linear color (the sRGB target encodes it)\nlayout(location = 1) out vec4 outNormal; // tangent space normal * 0.5 + 0.5\n\nfloat hash(vec2 p) {\n    p = fract(p * vec2(123.34, 456.21));\n    p += dot(p, p + 45.32);\n    return fract(p.x * p.y);\n}\n\nvec2 hash2(vec2 p) {\n    return vec2(hash(p), hash(p + 17.17));\n}\n\n// value noise, periodic: period cells along x and y\nfloat vnoise(vec2 uv, vec2 period) {\n    vec2 p = uv * period;\n    vec2 i = floor(p), f = fract(p);\n    vec2 u = f * f * (3.0 - 2.0 * f);\n    float a = hash(mod(i, period)), b = hash(mod(i + vec2(1.0, 0.0), period));\n    float c = hash(mod(i + vec2(0.0, 1.0), period)), d = hash(mod(i + vec2(1.0), period));\n    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);\n}\n\nfloat fbm(vec2 uv, vec2 period, int octaves) {\n    float sum = 0.0, amplitude = 0.5, norm = 0.0;\n    for(int i = 0; i < octaves; i++) {\n        sum += amplitude * vnoise(uv, period);\n        norm += amplitude;\n        period *= 2.0;\n        amplitude *= 0.5;\n        uv += 0.37; // decorrelate the octaves\n    }\n    return sum / norm;\n}\n\n// cellular noise, periodic: x distance to the nearest point, y to the second, z id of the nearest cell\nvec3 worley(vec2 uv, float period) {\n    vec2 p = uv * period;\n    vec2 i = floor(p), f = fract(p);\n    float f1 = 8.0, f2 = 8.0, id = 0.0;\n    for(int y = -1; y <= 1; y++) {\n        for(int x = -1; x <= 1; x++) {\n            vec2 cell = mod(i + vec2(x, y), period);\n            float d = length(vec2(x, y) + hash2(cell) - f);\n            if(d < f1) {\n                f2 = f1;\n                f1 = d;\n                id = hash(cell + 3.1);\n            } else if(d < f2) {\n                f2 = d;\n            }\n        }\n    }\n    return vec3(f1, f2, id);\n}\n\n// relief (0 .. 1) and color of a material at uv\nfloat material(vec2 uv, out vec3 albedo) {\n    if(layer == 0) {\n        // earth: lumps, fine grain, pebbles in some cells\n        float lumps = fbm(uv, vec2(6.0), 5);\n        float grain = fbm(uv, vec2(96.0), 3);\n        vec3 w = worley(uv, 28.0);\n        float pebble = smoothstep(0.3, 0.15, w.x) * step(0.82, w.z); // a few small stones\n        float height = lumps * 0.55 + grain * 0.25 + pebble * (0.4 - w.x);\n        albedo = mix(vec3(0.16, 0.10, 0.06), vec3(0.36, 0.25, 0.15), lumps * 0.7 + grain * 0.3);\n        albedo = mix(albedo, vec3(0.30, 0.26, 0.21) * (0.8 + 0.3 * w.z), pebble * 0.8);\n        albedo *= 0.7 + 0.45 * height;\n        return height;\n    }\n    if(layer == 1) {\n        // rock: horizontal strata, large fractured blocks with a few thin cracks, fine grain, lichen\n        float strata = fbm(uv, vec2(2.0, 20.0), 5);\n        float bumps = fbm(uv, vec2(10.0), 6);\n        vec3 w = worley(uv, 4.0);\n        // cracks only along some block edges (broken up by noise), and fainter hairline cracks\n        float crack = smoothstep(0.035, 0.0, w.y - w.x) * smoothstep(0.45, 0.6, fbm(uv, vec2(8.0), 3));\n        vec3 fine = worley(uv + 0.21, 16.0);\n        float hairline = smoothstep(0.02, 0.0, fine.y - fine.x) * smoothstep(0.55, 0.7, fbm(uv + 0.4, vec2(12.0), 3));\n        float height = bumps * 0.55 + strata * 0.35 + w.x * 0.1 - crack * 0.35 - hairline * 0.12;\n        float tone = fbm(uv, vec2(24.0), 4) * 0.45 + strata * 0.55;\n        albedo = mix(vec3(0.21, 0.20, 0.20), vec3(0.50, 0.48, 0.45), tone);\n        albedo *= 0.9 + 0.2 * w.z; // each block a bit different\n        albedo *= 0.85 + 0.3 * vnoise(uv, vec2(128.0)); // grain\n        float lichen = smoothstep(0.64, 0.78, fbm(uv + 0.5, vec2(10.0), 5));\n        albedo = mix(albedo, vec3(0.36, 0.38, 0.22), lichen * 0.45);\n        albedo *= 1.0 - crack * 0.5 - hairline * 0.2;\n        return height;\n    }\n    if(layer == 2) {\n        // grass: blades (fine streaks), clumps, yellowed patches, a little bare earth\n        float blades = vnoise(uv, vec2(192.0, 64.0)) * 0.6 + vnoise(uv + 0.3, vec2(64.0, 192.0)) * 0.4;\n        float clumps = fbm(uv, vec2(16.0), 4);\n        float patches = smoothstep(0.55, 0.8, fbm(uv, vec2(4.0), 4));\n        float height = blades * 0.55 + clumps * 0.45;\n        albedo = mix(vec3(0.05, 0.13, 0.025), vec3(0.17, 0.36, 0.07), clumps * 0.5 + blades * 0.5);\n        albedo = mix(albedo, vec3(0.34, 0.36, 0.10), patches * 0.45);\n        float bare = smoothstep(0.82, 0.92, vnoise(uv, vec2(40.0)));\n        albedo = mix(albedo, vec3(0.25, 0.17, 0.10), bare * 0.6);\n        albedo *= 0.75 + 0.5 * blades;\n        return height;\n    }\n    if(layer == 4) {\n        // sand: fine grain, ripples, a few small pebbles and darker damp patches\n        float ripples = sin((uv.y + fbm(uv, vec2(3.0), 3) * 0.3) * 6.2831853 * 14.0) * 0.5 + 0.5;\n        float grain = vnoise(uv, vec2(256.0));\n        vec3 w = worley(uv, 36.0);\n        float pebble = smoothstep(0.25, 0.12, w.x) * step(0.9, w.z);\n        float height = ripples * 0.08 + grain * 0.05 + fbm(uv, vec2(8.0), 4) * 0.35 + pebble * 0.2;\n        albedo = mix(vec3(0.46, 0.40, 0.28), vec3(0.60, 0.53, 0.39), fbm(uv, vec2(10.0), 4) * 0.7 + grain * 0.3);\n        albedo *= 0.96 + 0.06 * ripples;\n        albedo = mix(albedo, vec3(0.35, 0.33, 0.30), pebble * 0.8);\n        return height;\n    }\n    if(layer == 5) {\n        // small waves: rounded crests in all directions\n        float height = fbm(uv, vec2(5.0), 5) * 0.65 + fbm(uv + 0.5, vec2(17.0), 3) * 0.35;\n        albedo = vec3(0.0);\n        return height;\n    }\n    // snow: soft drifts, wind ripples, bluish hollows\n    float drifts = fbm(uv, vec2(5.0), 5);\n    float ripples = vnoise(uv, vec2(8.0, 48.0));\n    float height = drifts * 0.8 + ripples * 0.2;\n    albedo = mix(vec3(0.70, 0.78, 0.90), vec3(0.92, 0.94, 0.97), smoothstep(0.2, 0.7, height));\n    return height;\n}\n\nvoid main() {\n    vec2 uv = gl_FragCoord.xy / size;\n    vec3 albedo, unused;\n    float h = material(uv, albedo);\n    // normal from the relief (finite differences, wrapping around with the noise)\n    float hx = material(uv + vec2(1.0 / size, 0.0), unused);\n    float hy = material(uv + vec2(0.0, 1.0 / size), unused);\n    float strength = layer == 3 || layer == 4 ? 2.0 : layer == 2 ? 5.0 : layer == 5 ? 3.0 : 8.0;\n    vec3 n = normalize(vec3((h - hx) * size * strength / 64.0, (h - hy) * size * strength / 64.0, 1.0));\n    outAlbedo = vec4(albedo, 1.0);\n    outNormal = vec4(n * 0.5 + 0.5, 1.0);\n}\n"},46:e=>{e.exports="#version 300 es\nprecision highp float;\n\n// Camera under the water: a turquoise veil over the image, lit like the water body.\nuniform float veil;\n\nout vec4 fragColor;\n\n// Shared by the terrain and the sky shaders. Colors are linear; toneMap converts to the screen.\n\nuniform sampler2D skyLUT; // sky radiance per direction (sky_lut_fragment.glsl)\nuniform vec3 sunDir;      // towards the sun\nuniform vec3 lightDir;    // direction of the main light (the sun, or the moon at night)\nuniform vec3 lightColor;  // that light, once through the atmosphere\nuniform float exposure;   // higher at night\nuniform bool rawOutput;   // linear HDR output, no tone mapping (reflection of the water)\nuniform float underwaterDensity; // > 0 when the camera is under the water: fog of the water per meter\n\nconst float PI = 3.14159265;\n\n// valley mist: density decreasing with altitude. Kept light: the haze of the light shafts, which knows the shadows,\n// does most of the work, and a uniform mist would wash out the contrast of the shafts\nconst float MIST_DENSITY = 0.0003;\nconst float MIST_BASE = 15.0;\nconst float MIST_HEIGHT = 28.0;\n\nvec2 skyLUTCoord(vec3 dir) {\n    float elevation = asin(clamp(dir.z, -1.0, 1.0));\n    return vec2(atan(dir.y, dir.x) / (2.0 * PI) + 0.5, 0.5 + 0.5 * sign(elevation) * sqrt(abs(elevation) / (0.5 * PI)));\n}\n\n// radiance of the sky in a direction. The sky changes very fast in the last degree above the horizon (grazing rays\n// cross 1000 km of air): below 1.5 degrees, and below the horizon (what the fog of distant terrain shows), the sky\n// at 1.5 degrees is used, which avoids a visible line at the horizon\nvec3 skyRadiance(vec3 dir) {\n    float horizontal = length(dir.xy) + 1e-5;\n    dir = normalize(vec3(dir.xy + 1e-5, max(dir.z, 0.026 * horizontal))); // tan(1.5 degrees) = 0.026\n    return texture(skyLUT, skyLUTCoord(dir)).rgb;\n}\n\n// ambient light received by a surface: the sky from above (irradiance ~ pi x mean radiance, from a few directions\n// of the sky texture), light bounced by the ground from below\nvec3 ambientLight(vec3 normal) {\n    vec2 h = normalize(sunDir.xy + 1e-4);\n    vec3 sky = (2.0 * skyRadiance(vec3(0.0, 0.0, 1.0))\n        + skyRadiance(vec3(h * 0.87, 0.5)) + skyRadiance(vec3(-h * 0.87, 0.5))) * 0.25 * PI * 0.35;\n    vec3 ground = lightColor * max(-lightDir.z, 0.0) * 0.06;\n    return mix(ground, sky, normal.z * 0.5 + 0.5);\n}\n\n// optical depth of the valley mist along a ray (analytic integral of the exponential density)\nfloat mistDepth(vec3 origin, vec3 dir, float dist) {\n    float start = MIST_DENSITY * exp(-(origin.z - MIST_BASE) / MIST_HEIGHT);\n    float k = dir.z / MIST_HEIGHT;\n    return abs(k) < 1e-4 ? start * dist : start * (1.0 - exp(-k * dist)) / k;\n}\n\n// color of the water seen from inside, lit by the sky and the sun or moon\nvec3 underwaterColor() {\n    return vec3(0.004, 0.020, 0.026) * (ambientLight(vec3(0.0, 0.0, 1.0)) + lightColor * max(-lightDir.z, 0.0)) * 4.0;\n}\n\nvec3 toneMap(vec3 color) {\n    if(rawOutput) return color;\n    color *= exposure;\n    // ACES filmic curve (Narkowicz 2015 fit), then gamma\n    color = clamp((color * (2.51 * color + 0.03)) / (color * (2.43 * color + 0.59) + 0.14), 0.0, 1.0);\n    return pow(color, vec3(1.0 / 2.2));\n}\n\n\nvoid main() {\n    fragColor = vec4(toneMap(underwaterColor()) * veil, veil);\n}\n"},202:e=>{e.exports="#version 300 es\n\n// x, y, z in the chunk (7 bits each) | face direction (3 bits) | ambient occlusion (2 bits) | material (3 bits)\nlayout(location=0) in uint data;\n\nuniform mat4 viewProj;\nuniform vec3 chunkOrigin;\n\nout float vAO;\nout vec3 vPosition;\nout vec3 vNormal;\nflat out int vFace;\nflat out int vMaterial;\nout vec3 vLocal; // position in the chunk: small texture coordinates, precise far from the origin\n\nconst vec3 NORMALS[6] = vec3[6](\n    vec3(1, 0, 0), vec3(-1, 0, 0),\n    vec3(0, 1, 0), vec3(0, -1, 0),\n    vec3(0, 0, 1), vec3(0, 0, -1));\n\nconst float AO[4] = float[4](0.25, 0.5, 0.75, 1.0);\n\nvoid main() {\n    vec3 local = vec3(float(data & 127u), float((data >> 7) & 127u), float((data >> 14) & 127u));\n    int face = int((data >> 21) & 7u);\n    int ao = int((data >> 24) & 3u);\n    int material = int((data >> 26) & 7u);\n\n    vPosition = chunkOrigin + local;\n    vNormal = NORMALS[face];\n    vFace = face;\n    vMaterial = material;\n    vLocal = local;\n    vAO = AO[ao];\n    gl_Position = viewProj * vec4(vPosition, 1.0);\n}\n"},148:e=>{e.exports="#version 300 es\nprecision highp float;\nprecision highp int;\nprecision lowp usampler3D;\nprecision highp sampler2D;\nprecision highp sampler3D;\nprecision mediump sampler2DArray;\n\n// Water surface: waves, planar reflection of the scene (rendered mirrored below the water level), Fresnel, sun glint,\n// and the ground seen through the water, dimmed with the depth (premultiplied alpha over the terrain already drawn).\n\nuniform vec3 camPosition;\nuniform float fogDensity;\nuniform float waterTime;\nuniform float seaLevel;\nuniform sampler2D reflectionTex; // linear HDR, same screen coordinates as this pass\nuniform bool reflectionOn;\nuniform sampler2D halfDepth;     // depth of the terrain (half resolution), for the thickness of water\nuniform bool hasHalfDepth;\nuniform vec2 depthRange;\nuniform sampler2DArray voxelNormals; // layer 5: normal map of the small waves\n\nin vec3 vPosition;\nflat in int vFace;\nflat in vec3 vSkyUp;\nflat in vec3 vAmbientUp;\n\nout vec4 fragColor;\n\n// Shadow rays through the voxels of the window loaded around the camera (needs precision lowp usampler3D).\n// The window wraps around the textures in x and y: a column always lives in the same slot while it is loaded.\n\nuniform usampler3D brickTex;  // 1 texel = 2x2x2 voxels, 1 bit each: bit (x & 1) | (y & 1) << 1 | (z & 1) << 2\nuniform usampler3D coarseTex; // 1 texel = 8x8x8 voxels, 0 when they are all empty\nuniform vec3 windowMin;       // world position of the window corner (z = bottom of the world)\nuniform vec3 windowSize;      // in voxels\nuniform ivec3 brickOrigin;    // texel of the window corner in each texture\nuniform ivec3 coarseOrigin;\n\nconst int COARSE_POW = 3; // must match constants.js\nconst int MAX_STEPS = 256;\n\n// Voxel traversal towards the light: every voxel crossed by the ray is tested (no fixed step that could\n// miss a corner), empty 8^3 then 2^3 blocks are crossed in one step, and the ray stops as soon as it\n// leaves the window. Returns 1 when lit, 0 in the shadow.\nfloat castShadowRay(vec3 startPos, vec3 rd) {\n    rd = mix(rd, vec3(1e-6), lessThan(abs(rd), vec3(1e-6)));\n    vec3 invRd = 1.0 / rd;\n    vec3 towards = step(0.0, rd); // 1 on the axes where the ray goes up\n    vec3 ro = startPos - windowMin; // window coordinates: small numbers, so precise even far from the origin\n    ivec3 brickMask = textureSize(brickTex, 0) - 1;\n    ivec3 coarseMask = textureSize(coarseTex, 0) - 1;\n    float t = 0.0;\n\n    for(int i = 0; i < MAX_STEPS; i++) {\n        vec3 pos = ro + rd * t;\n        if(pos.z < 0.0) {\n            return 0.0; // below the world: rock\n        }\n        if(any(lessThan(pos.xy, vec2(0.0))) || any(greaterThanEqual(pos, windowSize))) {\n            return 1.0; // above the world, or out of the loaded window: lit\n        }\n        ivec3 cell = ivec3(pos);\n\n        // size (power of 2) of the empty box the ray is in\n        int boxPow;\n        if(texelFetch(coarseTex, ((cell >> COARSE_POW) + coarseOrigin) & coarseMask, 0).r == 0u) {\n            boxPow = COARSE_POW;\n        } else {\n            uint brick = texelFetch(brickTex, ((cell >> 1) + brickOrigin) & brickMask, 0).r;\n            if(brick == 0u) {\n                boxPow = 1;\n            } else if(((brick >> uint((cell.x & 1) | ((cell.y & 1) << 1) | ((cell.z & 1) << 2))) & 1u) != 0u) {\n                return 0.0; // Ombre\n            } else {\n                boxPow = 0;\n            }\n        }\n\n        // jump just past the exit of that box\n        vec3 boxMin = vec3((cell >> boxPow) << boxPow);\n        vec3 tExit = (boxMin + towards * float(1 << boxPow) - ro) * invRd;\n        t = min(min(tExit.x, tExit.y), tExit.z) + 1e-3;\n    }\n\n    return 1.0;\n}\n\n// Cheaper visibility of the light from a point in the air, for the light shafts: only the 8^3 coarse occupancy\n// (an occupied block counts as solid), and a bounded number of steps. 1 = lit.\nfloat coarseVisibility(vec3 startPos, vec3 rd, int maxSteps) {\n    rd = mix(rd, vec3(1e-6), lessThan(abs(rd), vec3(1e-6)));\n    vec3 invRd = 1.0 / rd;\n    vec3 towards = step(0.0, rd);\n    vec3 ro = startPos - windowMin;\n    ivec3 coarseMask = textureSize(coarseTex, 0) - 1;\n    float t = 0.0;\n    for(int i = 0; i < maxSteps; i++) {\n        vec3 pos = ro + rd * t;\n        if(pos.z < 0.0) return 0.0;\n        if(any(lessThan(pos.xy, vec2(0.0))) || any(greaterThanEqual(pos, windowSize))) return 1.0;\n        ivec3 block = ivec3(pos) >> COARSE_POW;\n        if(texelFetch(coarseTex, (block + coarseOrigin) & coarseMask, 0).r != 0u) return 0.0;\n        vec3 tExit = (vec3(block << COARSE_POW) + towards * float(1 << COARSE_POW) - ro) * invRd;\n        t = min(min(tExit.x, tExit.y), tExit.z) + 1e-3;\n    }\n    return 1.0;\n}\n\n// Shared by the terrain and the sky shaders. Colors are linear; toneMap converts to the screen.\n\nuniform sampler2D skyLUT; // sky radiance per direction (sky_lut_fragment.glsl)\nuniform vec3 sunDir;      // towards the sun\nuniform vec3 lightDir;    // direction of the main light (the sun, or the moon at night)\nuniform vec3 lightColor;  // that light, once through the atmosphere\nuniform float exposure;   // higher at night\nuniform bool rawOutput;   // linear HDR output, no tone mapping (reflection of the water)\nuniform float underwaterDensity; // > 0 when the camera is under the water: fog of the water per meter\n\nconst float PI = 3.14159265;\n\n// valley mist: density decreasing with altitude. Kept light: the haze of the light shafts, which knows the shadows,\n// does most of the work, and a uniform mist would wash out the contrast of the shafts\nconst float MIST_DENSITY = 0.0003;\nconst float MIST_BASE = 15.0;\nconst float MIST_HEIGHT = 28.0;\n\nvec2 skyLUTCoord(vec3 dir) {\n    float elevation = asin(clamp(dir.z, -1.0, 1.0));\n    return vec2(atan(dir.y, dir.x) / (2.0 * PI) + 0.5, 0.5 + 0.5 * sign(elevation) * sqrt(abs(elevation) / (0.5 * PI)));\n}\n\n// radiance of the sky in a direction. The sky changes very fast in the last degree above the horizon (grazing rays\n// cross 1000 km of air): below 1.5 degrees, and below the horizon (what the fog of distant terrain shows), the sky\n// at 1.5 degrees is used, which avoids a visible line at the horizon\nvec3 skyRadiance(vec3 dir) {\n    float horizontal = length(dir.xy) + 1e-5;\n    dir = normalize(vec3(dir.xy + 1e-5, max(dir.z, 0.026 * horizontal))); // tan(1.5 degrees) = 0.026\n    return texture(skyLUT, skyLUTCoord(dir)).rgb;\n}\n\n// ambient light received by a surface: the sky from above (irradiance ~ pi x mean radiance, from a few directions\n// of the sky texture), light bounced by the ground from below\nvec3 ambientLight(vec3 normal) {\n    vec2 h = normalize(sunDir.xy + 1e-4);\n    vec3 sky = (2.0 * skyRadiance(vec3(0.0, 0.0, 1.0))\n        + skyRadiance(vec3(h * 0.87, 0.5)) + skyRadiance(vec3(-h * 0.87, 0.5))) * 0.25 * PI * 0.35;\n    vec3 ground = lightColor * max(-lightDir.z, 0.0) * 0.06;\n    return mix(ground, sky, normal.z * 0.5 + 0.5);\n}\n\n// optical depth of the valley mist along a ray (analytic integral of the exponential density)\nfloat mistDepth(vec3 origin, vec3 dir, float dist) {\n    float start = MIST_DENSITY * exp(-(origin.z - MIST_BASE) / MIST_HEIGHT);\n    float k = dir.z / MIST_HEIGHT;\n    return abs(k) < 1e-4 ? start * dist : start * (1.0 - exp(-k * dist)) / k;\n}\n\n// color of the water seen from inside, lit by the sky and the sun or moon\nvec3 underwaterColor() {\n    return vec3(0.004, 0.020, 0.026) * (ambientLight(vec3(0.0, 0.0, 1.0)) + lightColor * max(-lightDir.z, 0.0)) * 4.0;\n}\n\nvec3 toneMap(vec3 color) {\n    if(rawOutput) return color;\n    color *= exposure;\n    // ACES filmic curve (Narkowicz 2015 fit), then gamma\n    color = clamp((color * (2.51 * color + 0.03)) / (color * (2.43 * color + 0.59) + 0.14), 0.0, 1.0);\n    return pow(color, vec3(1.0 / 2.2));\n}\n\n// Voxel clouds: a few layers of big blocks above the mountains, drifting with the wind (needs precision highp sampler3D).\n// A cell is filled or not, from the tiling noise texture of cloudNoise.js; rays cross the cells with a grid traversal.\n\nuniform sampler3D cloudNoise;  // r Perlin-Worley (puffs), g Worley fbm (weather)\nuniform float cloudTime;       // seconds, for the wind\nuniform float cloudCoverage;   // 0 clear .. 1 overcast\n\nconst vec3 CLOUD_CELL = vec3(8.0, 8.0, 6.0);\nconst int CLOUD_LAYERS = 4;\nconst float CLOUD_BOTTOM = 210.0;\nconst float CLOUD_TOP = CLOUD_BOTTOM + 24.0; // CLOUD_CELL.z * CLOUD_LAYERS\nconst vec2 WIND = vec2(6.0, 2.5);          